package java.util.function;
public interface DoubleUnaryOperator { double applyAsDouble(double value); default DoubleUnaryOperator compose(final DoubleUnaryOperator p){java.util.Objects.requireNonNull(p);return new DoubleUnaryOperator(){public double applyAsDouble(double v){return DoubleUnaryOperator.this.applyAsDouble(p.applyAsDouble(v));}};} default DoubleUnaryOperator andThen(final DoubleUnaryOperator p){java.util.Objects.requireNonNull(p);return new DoubleUnaryOperator(){public double applyAsDouble(double v){return p.applyAsDouble(DoubleUnaryOperator.this.applyAsDouble(v));}};} static DoubleUnaryOperator identity(){return new DoubleUnaryOperator(){public double applyAsDouble(double v){return v;}};} }
